<template>
  <el-dialog title="平台发货回传" :visible.sync="visible" width="min(1040px, 96vw)" append-to-body :close-on-click-modal="false" class="platform-shipping-dialog">
    <div v-loading="loading" class="shipping-body"><el-alert title="当前为模拟回传：验证包裹、平台子单和实际数量，不向天猫发送，也不重复扣库存。" type="info" :closable="false" show-icon /><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
      <template v-if="report"><p class="identity">{{ report.shipment_sn }} <platform-log-link :number="report.shipment_sn" number-type="SHIPMENT" /></p><p class="caption">店铺配置：{{ report.configuration.mode === 'SIMULATION' ? '模拟模式' : '未开启' }} · 每个实际包裹独立回传，支持多仓及同一子单分数量发货。</p>
        <div class="totals"><strong>模拟成功 {{ successQuantity }} 件</strong><span>待回传 / 回传中 {{ pendingCount }} 个包裹</span><span class="warning">失败 / 待确认 {{ problemCount }} 个包裹</span></div>
        <article v-for="task in report.tasks" :key="task.id" class="shipping-task"><div class="task-heading"><strong>{{ task.express_code }}</strong><el-tag :type="tone(task.state)" size="small">{{ labels[task.state] || task.state }}</el-tag><el-tag type="info" size="mini" effect="plain">模拟</el-tag><span>{{ task.quantity }} 件</span><el-button v-if="task.state === 'FAILED'" v-hasPermi="['order:shipment:platformShipping']" type="text" :disabled="!!busy || report.configuration.mode !== 'SIMULATION'" @click="act(task, 'retry')">按原快照重试</el-button><el-button v-if="task.state === 'UNKNOWN'" v-hasPermi="['order:shipment:platformShipping']" type="text" :disabled="!!busy" @click="act(task, 'query')">核对原回执</el-button></div><p v-if="task.last_error" class="warning">{{ task.last_error }}</p><p class="caption">提交尝试 {{ task.attempts }} 次 · 核对尝试 {{ task.query_attempts }} 次 · {{ task.success_at ? '成功时间 ' + task.success_at : '创建时间 ' + task.create_time }}</p><p v-if="task.platform_receipt" class="caption">模拟回执：{{ task.platform_receipt }}</p>
          <el-collapse><el-collapse-item title="查看本次包裹商品与回传快照" :name="String(task.id)"><p v-if="task.snapshot" class="caption">平台主单 {{ task.snapshot.platform_tid }} · OMS快递 {{ task.snapshot.carrier_code }} → 平台编码 {{ task.snapshot.platform_carrier_code }}</p><el-table :data="task.snapshot ? task.snapshot.lines : []" size="small"><el-table-column label="SKU" prop="sku_sn" min-width="160" /><el-table-column label="平台子单号" prop="platform_oid" min-width="210" /><el-table-column label="本包裹实际数量" prop="quantity" width="150" /></el-table><p v-if="task.snapshot_error" class="warning">{{ task.snapshot_error }}</p></el-collapse-item></el-collapse>
        </article>
        <section v-if="report.unsubmitted_packages.length" class="unsubmitted"><h4>尚未生成任务的包裹</h4><div v-for="pack in report.unsubmitted_packages" :key="pack.id"><strong>{{ pack.express_code }}</strong> · {{ pack.quantity }} 件 <span :class="pack.eligible ? 'caption' : 'warning'">{{ pack.eligible ? '已满足模拟回传条件' : pack.reason }}</span></div><el-button v-hasPermi="['order:shipment:platformShipping']" type="primary" size="small" :disabled="!canSubmit || !!busy" :loading="busy === 'submit'" @click="submit">生成模拟回传任务</el-button></section><el-empty v-if="!report.tasks.length && !report.unsubmitted_packages.length" description="暂无实际包裹，请先完成出库入账并关联运单" :image-size="60" />
        <el-collapse class="logs"><el-collapse-item title="平台回传业务处理记录" name="logs"><el-table :data="report.logs" size="small"><el-table-column label="时间 / 操作人" min-width="180"><template slot-scope="s">{{ s.row.create_time }}<div class="caption">{{ s.row.operator_name }}</div></template></el-table-column><el-table-column label="动作 / 结果" width="160"><template slot-scope="s">{{ actions[s.row.action] || s.row.action }} · {{ labels[s.row.result] || s.row.result }}</template></el-table-column><el-table-column label="说明" prop="message" min-width="250" /></el-table></el-collapse-item></el-collapse>
      </template>
    </div><span slot="footer"><span class="caption">{{ polling ? '正在自动刷新进度' : '可手动刷新进度' }}</span><el-button :disabled="!!busy" :loading="loading" @click="refresh">刷新进度</el-button><el-button :disabled="!!busy" @click="visible=false">关闭</el-button></span>
  </el-dialog>
</template>
<script>
import PlatformLogLink from '@/views/oms/channel/PlatformLogLink'
import { platformShippingReport, platformShippingSubmit, platformShippingAction } from '@/api/order'
export default { components: { PlatformLogLink },
  data() { return { visible: false, loading: false, id: null, report: null, error: '', busy: '', requestId: 0, timer: null, polling: false, signature: '', labels: { PENDING: '待回传', PROCESSING: '回传中', SUCCESS: '模拟回传成功', FAILED: '回传失败', UNKNOWN: '结果待确认' }, actions: { ENQUEUE: '生成任务', SEND: '模拟发送', QUERY: '核对原回执', RETRY: '人工重试' } } },
  computed: { successQuantity() { return this.report.tasks.filter(t => t.state === 'SUCCESS').reduce((n, t) => n + Number(t.quantity), 0) }, pendingCount() { return this.report.tasks.filter(t => ['PENDING', 'PROCESSING'].includes(t.state)).length }, problemCount() { return this.report.tasks.filter(t => ['FAILED', 'UNKNOWN'].includes(t.state)).length }, canSubmit() { return this.report && this.report.unsubmitted_packages.length && this.report.unsubmitted_packages.every(p => p.eligible) } },
  watch: { visible(v) { if (!v) { this.requestId++; this.stop() } } }, beforeDestroy() { this.requestId++; this.stop() },
  methods: {
    tone(state) { return state === 'SUCCESS' ? 'success' : state === 'FAILED' ? 'danger' : state === 'UNKNOWN' ? 'warning' : 'info' },
    stop() { clearTimeout(this.timer); this.timer = null; this.polling = false },
    open(id) { this.stop(); this.id = id; this.report = null; this.signature = ''; this.error = ''; this.visible = true; this.refresh() },
    accept(report) { const signature = report.tasks.map(t => t.id + ':' + t.state).join(','); if (this.signature && this.signature !== signature) this.$emit('changed'); this.signature = signature; this.report = report },
    async refresh() { this.stop(); if (!this.visible || this.busy) return; const seq = ++this.requestId; this.loading = true; this.error = ''; try { const r = await platformShippingReport(this.id); if (seq !== this.requestId) return; this.accept(r.data); if (this.report.tasks.some(t => ['PENDING', 'PROCESSING', 'UNKNOWN'].includes(t.state)) && this.report.configuration.mode === 'SIMULATION') { this.polling = true; this.timer = setTimeout(() => this.refresh(), 5000) } } catch (_) { if (seq === this.requestId) this.error = '回传进度加载失败，请刷新重试；已有任务保留。' } finally { if (seq === this.requestId) this.loading = false } },
    async submit() { if (!this.canSubmit || this.busy) return; this.busy = 'submit'; this.stop(); this.requestId++; try { const r = await platformShippingSubmit(this.id); this.accept(r.data); this.$emit('changed'); this.$message.success('模拟回传任务已生成') } finally { this.busy = ''; await this.refresh() } },
    async act(task, action) { if (this.busy) return; this.busy = String(task.id); this.stop(); this.requestId++; try { const r = await platformShippingAction(this.id, task.id, action); this.accept(r.data); this.$emit('changed') } finally { this.busy = ''; await this.refresh() } }
  }
}
</script>
<style scoped>.shipping-body{max-height:calc(100vh - 260px);overflow:auto}.identity{overflow-wrap:anywhere;font-weight:600}.caption{font-size:12px;color:#8490a2;line-height:1.7}.totals,.task-heading{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.totals{padding:14px;background:#f5f8fc;border-radius:8px;margin:14px 0}.shipping-task,.unsubmitted{border:1px solid #e4e9f0;border-radius:8px;padding:14px;margin:12px 0}.task-heading strong{overflow-wrap:anywhere}.warning{color:#b87a1b;font-size:13px;line-height:1.7}.unsubmitted>div{margin:10px 0;overflow-wrap:anywhere}.logs{margin-top:16px}.platform-shipping-dialog /deep/ .el-dialog{margin-top:5vh!important}.shipping-task /deep/ .el-collapse-item__header{font-size:13px;color:#52647c}.el-dialog__footer .caption{margin-right:12px}</style>
